TOOL.Category="GRM";TOOL.Name="#tool.grm_jobs.name";TOOL.Command=nil;TOOL.ConfigName="";TOOL.ClientConVar={point_type="courier",point_name="",spawn_bin="1",make_perm="1"}
if CLIENT then language.Add("tool.grm_jobs.name","GRM Точки работ");language.Add("tool.grm_jobs.desc","Маршруты курьера, мусоровоза и такси");language.Add("tool.grm_jobs.0","ЛКМ: поставить точку • ПКМ: настройки • R: удалить ближайшую")end
function TOOL:LeftClick(tr)if CLIENT then return true end;local ply=self:GetOwner();if not(IsValid(ply)and ply:IsSuperAdmin()and tr and tr.Hit and GRM.Jobs and GRM.Jobs.AddWorkPoint)then return false end;local typ=self:GetClientInfo("point_type");local name=self:GetClientInfo("point_name");local ok,rec=GRM.Jobs.AddWorkPoint(typ,name,tr.HitPos);if not ok then return false end
 if typ=="garbage"and self:GetClientInfo("spawn_bin")~="0"then local e=ents.Create("grm_garbage_bin");if IsValid(e)then e:SetPos(tr.HitPos+tr.HitNormal*4);e:SetAngles(Angle(0,ply:EyeAngles().y,0));e:SetBinName(rec.name);e:Spawn();e:Activate();e.GRMJobPointID=rec.id;if self:GetClientInfo("make_perm")~="0"and GRM.Perm and GRM.Perm.Add then GRM.Perm.Add(ply,e,{ownerKind="server",freeze=true,label="Мусорный контейнер"})end end end
 if GRM.Notify then GRM.Notify(ply,"Точка работы добавлена: "..tostring(rec.name),90,225,145)end;return true end
function TOOL:RightClick()if CLIENT then return true end;local ply=self:GetOwner();if IsValid(ply)and ply:IsSuperAdmin()and GRM.Jobs and GRM.Jobs.OpenAdmin then GRM.Jobs.OpenAdmin(ply)return true end return false end
function TOOL:Reload(tr)if CLIENT then return true end;local ply=self:GetOwner();if not(IsValid(ply)and ply:IsSuperAdmin()and GRM.Jobs)then return false end;local pos=tr and tr.HitPos or ply:GetPos();local ok,rec=GRM.Jobs.RemoveNearestWorkPoint(pos,180);if ok then for _,e in ipairs(ents.FindByClass("grm_garbage_bin"))do if IsValid(e)and(e.GRMJobPointID==rec.id or e:GetPos():DistToSqr(Vector(rec.pos.x,rec.pos.y,rec.pos.z))<100*100)then if GRM.Perm and GRM.Perm.Remove then GRM.Perm.Remove(ply,e,false)end;e:Remove()end end;if GRM.Notify then GRM.Notify(ply,"Точка удалена.",230,175,80)end end;return ok==true end
function TOOL.BuildCPanel(p)local combo=p:ComboBox("Работа / тип точки","grm_jobs_point_type");combo:AddChoice("Курьер — доставка","courier");combo:AddChoice("Мусоровоз — контейнер","garbage");combo:AddChoice("Мусоровоз — свалка","dump");combo:AddChoice("Такси — стоянка/ориентир","taxi_pickup");combo:AddChoice("Такси — ориентир назначения","taxi_dropoff");p:TextEntry("Название точки","grm_jobs_point_name");p:CheckBox("Создать физическую мусорку для garbage","grm_jobs_spawn_bin");p:CheckBox("Сохранить мусорку через Perm","grm_jobs_make_perm");p:Button("Открыть полную настройку","grm_jobs_admin");p:Help("ЛКМ ставит типизированную точку. Для мусорного контейнера одновременно создаётся entity, в которой работник ищет коробку отходов.")end
